/* HAMU 2FA — sade ve stabil akış (tek dosya)
   - Modal kapanmaz; alert yok
   - API: /index.php?api=2fa&op=...
   - İki yöntem de devre dışı => backup_clear + 2fa_s:false (API bunu hallediyor)
*/
(function (w, d) {
  "use strict";

  const __  = (k, f) => { try { return w.l_js__ ? w.l_js__(k) : (f || k); } catch { return f || k; } };
  const el  = (id) => d.getElementById(id);
  const on  = (e, t, fn) => e && e.addEventListener(t, fn);
  const show= (e) => e && e.classList.remove("d-none");
  const hide= (e) => e && e.classList.add("d-none");
  const lock= (e, v) => e && (e.disabled = !!v);
  const api = (op) => `/index.php?api=2fa&op=${encodeURIComponent(op)}`;

  async function getJSON(url) {
    const r = await fetch(url, { credentials: "same-origin" });
    return r.json().catch(() => ({}));
  }
  async function postJSON(url, body) {
    const r = await fetch(url, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body || {})
    });
    return r.json().catch(() => ({}));
  }
  const csrf = () => { try { return w.HAMU?.util?.getCsrfToken?.() || ""; } catch { return ""; } };
  function setTxt(e, t, cls) { if (!e) return; if (cls) e.className = cls; e.textContent = t || ""; }

  const UI = {
    twofaSwitch: el("2fa_s"),
    email: {
      addr:    el("email_address_s"),
      send:    el("emailSendBtn"),
      code:    el("emailCode"),
      verify:  el("emailVerifyBtn"),
      disable: el("emailDisableBtn"),
      badge:   el("emailBadge"),
      status:  el("emailStatus"),
      verifyRow: el("emailVerifyRow"),
      backupBox: el("backupBoxEmail"),
      backupWarn: el("backupWarnEmail"),
    },
    app: {
      start:   el("totpStartBtn"),
      code:    el("totpCode"),
      verify:  el("totpVerifyBtn"),
      disable: el("totpDisableBtn"),
      badge:   el("appBadge"),
      status:  el("totpStatus"),
      qrBox:   el("qrBox"),
      qr:      el("qrCanvasHolder"),
      secret:  el("totpSecretText"),
      hidden:  el("totpSecretB32Hidden"),
      verifyRow: el("totpVerifyRow"),
      backupBox: el("backupBoxApp"),
      backupWarn: el("backupWarnApp"),
    },
    backup: {
      box:  el("backupBox"),
      list: el("backupList"),
      save: el("backupSaveBtn"),
      regen:el("backupGenBtn"),
      warn: el("backupWarn"),
    }
  };

  const S = { emailVerified:false, appLinked:false, backupExists:false, method:null, backupListOpen:false };
  const hasAny2FA = () => S.emailVerified || S.appLinked;

  function paintBadges() {
    if (UI.email.badge) {
      if (S.emailVerified) {
        UI.email.badge.textContent = __("verified","doğrulandı");
        UI.email.badge.className = "badge bg-success text-white";
        hide(UI.email.verifyRow); lock(UI.email.addr, true); show(UI.email.disable);
      } else {
        UI.email.badge.textContent = __("not_verified","doğrulanmadı");
        UI.email.badge.className = "badge bg-secondary text-white";
        lock(UI.email.addr, false); hide(UI.email.disable);
      }
    }
    if (UI.app.badge) {
      if (S.appLinked) {
        UI.app.badge.textContent = __("linked","kurulu");
        UI.app.badge.className = "badge bg-success text-white";
        hide(UI.app.qrBox); hide(UI.app.verifyRow); show(UI.app.disable);
      } else {
        UI.app.badge.textContent = __("setup","setup");
        UI.app.badge.className = "badge bg-secondary text-white";
        hide(UI.app.disable);
      }
    }
    if (UI.twofaSwitch) UI.twofaSwitch.checked = hasAny2FA();
  }

  function updateBackupButtons() {
    if (!UI.backup.box) return;
    if (!hasAny2FA()) { hide(UI.backup.save); hide(UI.backup.regen); hide(UI.backup.list); return; }
    if (S.backupListOpen) { show(UI.backup.save); hide(UI.backup.regen); show(UI.backup.list); }
    else { hide(UI.backup.save); show(UI.backup.regen); hide(UI.backup.list); }
  }

  function paintBackupVisibility() {
    if (UI.backup.box) {
      if (!hasAny2FA()) { hide(UI.backup.box); S.backupListOpen=false; }
      else { show(UI.backup.box); }
    }
    [UI.email.backupBox, UI.app.backupBox].forEach((box, i) => {
      if (!box) return;
      const should = i === 0 ? S.emailVerified : S.appLinked;
      should || (S.emailVerified && S.appLinked) ? show(box) : hide(box);
    });

    const warnTxt = S.backupExists ? __("backup_saved","Yedek kodlar kayıtlı") : "";
    [UI.backup.warn, UI.email.backupWarn, UI.app.backupWarn].forEach(w => {
      if (!w) return;
      if (!hasAny2FA()) { hide(w); return; }
      if (S.backupExists) { w.textContent = warnTxt; show(w); } else { hide(w); }
    });

    updateBackupButtons();
  }

  async function fetchStatus() {
    const r = await getJSON(api("status"));
    S.emailVerified = !!r.email_verified;
    S.appLinked     = !!r.app_linked;
    S.backupExists  = !!r.backup_has;
    S.method        = r.method || null;
  }
  async function refreshBackupState() {
    const r = await postJSON(api("backup_list"), {});
    S.backupExists = !!r.has;
    return S.backupExists;
  }

  async function sendMail() {
    const to = (UI.email.addr?.value || "").trim();
    if (!to) { setTxt(UI.email.status, __("enter_email","E-posta giriniz"), "text-danger"); return; }
    lock(UI.email.send, true); setTxt(UI.email.status, __("sending","Gönderiliyor…"));
    const r = await postJSON(api("email_send"), { to });
    lock(UI.email.send, false);
    if (!r?.ttl) { setTxt(UI.email.status, __("send_failed","Gönderilemedi"), "text-danger"); return; }
    show(UI.email.verifyRow);
    setTxt(UI.email.status, __("code_sent","Kod gönderildi; gelen kodu giriniz"), "text-success");
  }
  async function verifyMail() {
    const code = (UI.email.code?.value || "").trim();
    if (!code) return;
    lock(UI.email.verify, true); setTxt(UI.email.status, __("verifying","Doğrulanıyor…"));
    const r = await postJSON(api("email_verify"), { code });
    lock(UI.email.verify, false);
    if (!r?.verified) { setTxt(UI.email.status, __("invalid_or_expired_code","Kod geçersiz/expired"), "text-danger"); return; }

    await fetchStatus(); paintBadges();
    await refreshBackupState();
    if (!S.backupExists) { await generateBackupInteractive(true); }
    else { S.backupListOpen=false; updateBackupButtons(); }
    paintBackupVisibility();
  }
  async function disableMail() {
    lock(UI.email.disable, true); setTxt(UI.email.status, __("disabling","Kapatılıyor…"));
    await postJSON(api("email_disable"), {});
    await fetchStatus(); paintBadges();
    await refreshBackupState(); S.backupListOpen=false; paintBackupVisibility();
    lock(UI.email.disable, false); setTxt(UI.email.status, __("disabled","Devre dışı"), "text-muted");
  }

  async function startApp() {
    lock(UI.app.start, true); setTxt(UI.app.status, __("preparing_qr","QR hazırlanıyor…"));
    const acc = (UI.email.addr?.value || "").trim() || "user@local";
    const r = await postJSON(api("totp_enroll_start"), { account: acc, issuer: "HAMU DevPanel" });
    lock(UI.app.start, false);
    if (!r?.otpauth_uri || !r?.secret_b32) { setTxt(UI.app.status, __("qr_prepare_failed","QR oluşturulamadı"), "text-danger"); return; }
    if (UI.app.hidden) UI.app.hidden.value = r.secret_b32;
    if (UI.app.secret) UI.app.secret.textContent = r.secret_b32;
    if (UI.app.qr) {
      UI.app.qr.innerHTML = "";
      try { if (w.QRCode) new w.QRCode(UI.app.qr, { text: r.otpauth_uri, width: 128, height: 128 });
            else UI.app.qr.textContent = __("qr_unavailable","QR gösterilemedi"); }
      catch { UI.app.qr.textContent = __("qr_unavailable","QR gösterilemedi"); }
    }
    show(UI.app.qrBox); show(UI.app.verifyRow);
    setTxt(UI.app.status, __("scan_and_enter_code","Uygulamada tara, 6 haneli kodu gir"), "text-muted");
  }
  async function verifyApp() {
    const c = (UI.app.code?.value || "").trim();
    if (!c) return;
    lock(UI.app.verify, true); setTxt(UI.app.status, __("verifying","Doğrulanıyor…"));
    const r = await postJSON(api("totp_enroll_check"), { code: c });
    lock(UI.app.verify, false);
    if (!r?.enrolled) { setTxt(UI.app.status, __("verify_failed_retry","Kod olmadı, tekrar deneyin"), "text-danger"); return; }

    await fetchStatus(); paintBadges();
    await refreshBackupState();
    if (!S.backupExists && !S.emailVerified) { await generateBackupInteractive(true); }
    else { S.backupListOpen=false; updateBackupButtons(); }
    paintBackupVisibility();
    setTxt(UI.app.status, __("linked","Kurulum tamam"), "text-success");
  }
  async function disableApp() {
    lock(UI.app.disable, true); setTxt(UI.app.status, __("disabling","Kapatılıyor…"));
    await postJSON(api("totp_disable"), {});
    await fetchStatus(); paintBadges();
    await refreshBackupState(); S.backupListOpen=false; paintBackupVisibility();
    lock(UI.app.disable, false); setTxt(UI.app.status, __("disabled","Devre dışı"), "text-muted");
  }

  async function generateBackupInteractive(auto=false) {
    if (!hasAny2FA()) return;
    const r = await postJSON(api("backup_generate"), {});
    if (!r?.success) return;

    if (UI.backup.list) {
      UI.backup.list.innerHTML = "";
      (r.codes || []).forEach((c) => {
        const li = d.createElement("li");
        li.className = "list-group-item d-flex justify-content-between align-items-center";
        li.appendChild(d.createTextNode(c));
        const btn = d.createElement("button");
        btn.className = "btn btn-sm btn-outline-secondary";
        btn.textContent = __("copy","Kopyala");
        btn.addEventListener("click", () => w.navigator?.clipboard?.writeText(c));
        li.appendChild(btn);
        UI.backup.list.appendChild(li);
      });
    }
    S.backupListOpen = true; updateBackupButtons();
    if (UI.backup.warn && auto) { UI.backup.warn.textContent = __("backup_auto_gen","Yedek kodlar hazır — lütfen kaydedin"); show(UI.backup.warn); }
  }
  async function backupSave() {
    const codes = [...(UI.backup.list?.querySelectorAll("li") || [])]
      .map(li => (li.childNodes[0]?.nodeValue || "").trim()).filter(Boolean);
    if (!codes.length) return;

    await postJSON(api("backup_save"), { codes });
    await postJSON(api("backup_ack"),  {});

    const blob = new Blob([codes.join("\n")], { type: "text/plain" });
    const a = d.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "hamu-backup-codes.txt";
    d.body.appendChild(a); a.click(); a.remove();

    hide(UI.backup.list); S.backupListOpen = false;
    await refreshBackupState(); updateBackupButtons(); paintBackupVisibility();
  }

  function bind() {
    on(UI.email.send,   "click", sendMail);
    on(UI.email.verify, "click", verifyMail);
    on(UI.email.disable,"click", disableMail);
    on(UI.app.start,    "click", startApp);
    on(UI.app.verify,   "click", verifyApp);
    on(UI.app.disable,  "click", disableApp);
    on(UI.backup.regen, "click", () => generateBackupInteractive(false));
    on(UI.backup.save,  "click", backupSave);
  }
  async function boot() {
    await fetchStatus(); paintBadges();
    await refreshBackupState(); S.backupListOpen=false;
    paintBackupVisibility(); bind();
  }
  if (d.readyState === "loading") d.addEventListener("DOMContentLoaded", boot);
  else boot();
})(window, document);
// Radio name: 2fa_method_s  (değerler: "email" | "app")
document.querySelectorAll('input[name="2fa_method_s"]').forEach(r => {
  r.addEventListener('change', async (e) => {
    const method = e.target.value; // "email" | "app"
    await fetch('/index.php?api=config', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ '2fa_method_s': method, csrf_token: (window.HAMU?.util?.getCsrfToken?.()||'') })
    });
    // İsteğe bağlı: ekranda ufak bir “kaydedildi” statüsü yaz
  });
});